    private static LeftJoin innerRightOnlyW(TupleExpr root) {
        return nodes(root).stream().filter(LeftJoin.class::isInstance).map(LeftJoin.class::cast)
                .filter(leftJoin -> leftJoin.getLeftArg().getBindingNames().contains("v")
                        && !leftJoin.getLeftArg().getBindingNames().contains("w")
                        && leftJoin.getRightArg().getBindingNames().containsAll(Set.of("w", "tag")))
                .findFirst().orElseThrow();
    }

    private static LeftJoin enclosingLeftJoin(TupleExpr root, LeftJoin child) {
        return nodes(root).stream().filter(LeftJoin.class::isInstance).map(LeftJoin.class::cast)
                .filter(leftJoin -> leftJoin != child && nodes(leftJoin.getRightArg()).contains(child)
                        && leftJoin.getLeftArg().getBindingNames().contains("w"))
                .findFirst().orElseThrow();
    }

