    private boolean assertPublicPipelineRows(String label, List<Statement> data, TupleExpr sourceRoot, BindingSet input,
            boolean experimental, boolean typed, boolean compareRawAndPublicOrdinaryBag,
            TestReporter reporter) {
        var source = SealedBoundaryTestSupport.source(data);
        DefaultEvaluationStrategy ordinary = SealedBoundaryTestSupport.ordinary(source, experimental);
        List<BindingSet> rawOrdinary = SealedBoundaryTestSupport.drain(ordinary.precompile(sourceRoot.clone()), input,
                false);
        TupleExpr ordinaryOptimizedRoot = sourceRoot.clone();
        TupleExpr ordinaryOptimized = ordinary.optimize(ordinaryOptimizedRoot, new EvaluationStatistics(), input);
        List<BindingSet> expected = SealedBoundaryTestSupport.drain(ordinary.precompile(ordinaryOptimized), input,
                false);
        boolean sameEntryMappingBag = mappingBag(rawOrdinary).equals(mappingBag(expected));
        if (compareRawAndPublicOrdinaryBag) {
            assertTrue(sameEntryMappingBag,
                    "raw and normally optimized ordinary query preserve the exact RDF mapping bag for this same query-entry contract");
        }

        TupleExpr rawNativeRoot = sourceRoot.clone();
        var rawNative = SealedBoundaryTestSupport.nativeStrategy(source, experimental);
        List<BindingSet> rawRows = SealedBoundaryTestSupport.drain(rawNative.precompile(rawNativeRoot), input, typed);
        SealedBoundaryTestSupport.assertRows(rawOrdinary, rawRows);
        assertEquals(source.opened, source.closed, "raw compile control closes every opened native reader");

        var statistics = new EvaluationStatistics();
        var strategy = new LmdbNativeEvaluationStrategy(source, null, null, 0L, statistics, false);
        strategy.setQueryExecutionPolicy(org.eclipse.rdf4j.query.QueryExecutionPolicy.of(experimental));
        var trace = new ScopeMarkerTrace(new LmdbQueryOptimizerPipeline(strategy, source, statistics));
        strategy.setOptimizerPipeline(trace);
        LmdbNativeEvaluationStrategy worker = strategy.forWorker(source);
        TupleExpr optimizedRoot = worker.optimize(sourceRoot, statistics, input);
        assertTrue(trace.sawUnionScopeChangeOptimizer, "normal public optimizer pipeline ran its real marker pass");
        optimizedRoot.setExecutionSummaryEnabled(true);
        for (TupleExpr node : nodes(optimizedRoot)) {
            node.setExecutionSummaryEnabled(true);
        }
        List<BindingSet> actual = SealedBoundaryTestSupport.drain(worker.precompile(optimizedRoot), input, typed);
        SealedBoundaryTestSupport.assertRows(expected, actual);
        assertEquals(source.opened, source.closed, "public optimized evaluation closes every native record reader");
        SealedBoundaryTestSupport.report(optimizedRoot, reporter);
        reporter.publishEntry("scopeMarkerTopology", trace.report());
        reporter.publishEntry("publicComposedOwner", Boolean.toString(hasComposedOwner(optimizedRoot)));
        List<String> actualOwners = nodes(optimizedRoot).stream()
                .filter(node -> node.getStringMetricActual("nativeExecutionPath") != null
                        || node.getStringMetricPlanned(LmdbNativeExplain.PHYSICAL_PLAN) != null)
                .map(node -> node.getClass().getSimpleName() + " path="
                        + node.getStringMetricActual("nativeExecutionPath") + " plan="
                        + node.getStringMetricPlanned(LmdbNativeExplain.PHYSICAL_PLAN))
                .toList();
        PUBLIC_PIPELINE_TRACES.add(label + "\n" + trace.report() + "\ncomposedOwner="
                + hasComposedOwner(optimizedRoot) + "\nrawPublicMappingBagEqual=" + sameEntryMappingBag
                + "\nactualOwners=" + actualOwners);
        return hasComposedOwner(optimizedRoot);
    }

    private static Map<BindingSet, Integer> mappingBag(List<BindingSet> rows) {
        Map<BindingSet, Integer> result = new HashMap<>();
        rows.forEach(row -> result.merge(row, 1, Integer::sum));
        return result;
    }

    private static boolean hasComposedOwner(TupleExpr root) {
        for (TupleExpr node : nodes(root)) {
            String path = node.getStringMetricActual("nativeExecutionPath");
            String plan = node.getStringMetricPlanned(LmdbNativeExplain.PHYSICAL_PLAN);
            if (path != null && !path.contains(LmdbNativeAttemptMetrics.PATH_GENERIC_FALLBACK)
                    && !path.contains("nativeProjectionBoundary") && plan != null && plan.contains("LeftJoin(")) {
                return true;
            }
        }
        return false;
    }

    private static String markerTopology(TupleExpr root) {
        return nodes(root).stream().filter(TupleExprs::isVariableScopeChange)
                .map(node -> node.getClass().getSimpleName()).toList().toString();
    }

    private static final class ScopeMarkerTrace implements QueryOptimizerPipeline {
        private final QueryOptimizerPipeline delegate;
        private final List<QueryOptimizer> wrapped = new ArrayList<>();
        private final java.util.IdentityHashMap<QueryOptimizer, QueryOptimizer> originals = new java.util.IdentityHashMap<>();
        private String beforePipeline;
        private String beforeScopeOptimizer;
        private String afterScopeOptimizer;
        private String afterPipeline;
        private String beforeShape;
        private String afterScopeShape;
        private String afterShape;
        private boolean started;
        private boolean sawUnionScopeChangeOptimizer;

        private ScopeMarkerTrace(QueryOptimizerPipeline delegate) {
            this.delegate = delegate;
            for (QueryOptimizer original : delegate.getOptimizers()) {
                QueryOptimizer observer = (tupleExpr, dataset, bindings) -> {
                    if (!started) {
                        started = true;
                        beforePipeline = markerTopology(tupleExpr);
                        beforeShape = tupleExpr.toString();
                    }
                    if (original instanceof UnionScopeChangeOptimizer) {
                        sawUnionScopeChangeOptimizer = true;
                        beforeScopeOptimizer = markerTopology(tupleExpr);
                    }
                    original.optimize(tupleExpr, dataset, bindings);
                    if (original instanceof UnionScopeChangeOptimizer) {
                        afterScopeOptimizer = markerTopology(tupleExpr);
                        afterScopeShape = tupleExpr.toString();
                    }
                    afterPipeline = markerTopology(tupleExpr);
                    afterShape = tupleExpr.toString();
                };
                originals.put(observer, original);
                wrapped.add(observer);
            }
        }

        @Override
        public Iterable<QueryOptimizer> getOptimizers() {
            return wrapped;
        }

        @Override
        public BindingSet getOptimizerInputBindings(QueryOptimizer optimizer, BindingSet initialBindings) {
            QueryOptimizer original = originals.get(optimizer);
            return delegate.getOptimizerInputBindings(original == null ? optimizer : original, initialBindings);
        }

        private String report() {
            return "before=" + beforePipeline + "\nbefore UnionScopeChangeOptimizer=" + beforeScopeOptimizer
                    + "\nafter UnionScopeChangeOptimizer=" + afterScopeOptimizer + "\nafter=" + afterPipeline
                    + "\nbeforeShape=" + beforeShape + "\nafterScopeShape=" + afterScopeShape
                    + "\nafterShape=" + afterShape;
        }
    }
    private static void markPublicVisibility(Union union) {
        // This is the public algebra visibility contract, matching TupleExprBuilder; no runtime state or algorithm is assigned.
        union.setVariableScopeChange(true);
        ((org.eclipse.rdf4j.query.algebra.VariableScopeChange) union.getLeftArg()).setVariableScopeChange(true);
        ((org.eclipse.rdf4j.query.algebra.VariableScopeChange) union.getRightArg()).setVariableScopeChange(true);
    }
